<?php
defined( 'ABSPATH' ) || exit;
class AMANAH_SEO_AI_Content_Generation_Controller {
	private $generator,$repository;
	public function __construct($generator,$repository){$this->generator=$generator;$this->repository=$repository;}
	public function register(){add_action('admin_menu',array($this,'menu'),30);add_action('rest_api_init',array($this,'routes'));}
	public function menu(){add_submenu_page('amanah-seo','Article Generation','Article Generation','edit_posts','amanah-content-generation',array($this,'render'),0);}
	public function routes(){register_rest_route('amanah/v1','/content/generate',array('methods'=>'POST','callback'=>array($this,'rest_generate'),'permission_callback'=>function($r){return current_user_can('edit_posts')&&absint($r->get_param('content_brief_id'))>0;}));register_rest_route('amanah/v1','/content/refine',array('methods'=>'POST','callback'=>array($this,'rest_refine'),'permission_callback'=>function($r){return current_user_can('edit_posts')&&absint($r->get_param('content_brief_id'))>0;}));register_rest_route('amanah/v1','/content/approve',array('methods'=>'POST','callback'=>array($this,'rest_approve'),'permission_callback'=>function($r){return current_user_can('edit_posts')&&absint($r->get_param('content_brief_id'))>0;}));}
	public function rest_refine($request){$brief=$request->get_json_params();$brief=is_array($brief)?$brief:array();$brief['content_brief_id']=absint($request->get_param('content_brief_id'));$brief['post_id']=absint($request->get_param('post_id')?:($brief['post_id']??0));$current=isset($brief['current_package'])&&is_array($brief['current_package'])?$brief['current_package']:array();$r=$this->generator->refine($brief,$current,get_current_user_id(),sanitize_textarea_field($brief['refinement_instruction']??''));if(is_wp_error($r))return new WP_REST_Response(array('success'=>false,'message'=>$r->get_error_message()),502);return rest_ensure_response(array('success'=>true,'data'=>$r));}
	public function rest_approve($request){$id=absint($request->get_param('content_brief_id'));$r=$this->repository->latest($id);if(!$r)return new WP_REST_Response(array('success'=>false,'message'=>'Article Package not found.'),404);if('READY_FOR_HUMAN_REVIEW'!==$r->get_status())return new WP_REST_Response(array('success'=>false,'message'=>'Article Package is not ready for human approval.'),409);$approved=new AMANAH_SEO_AI_Article_Package($r->get_package_id(),$r->get_content_brief_id(),$r->get_version(),$r->get_parent_version(),'HUMAN_APPROVED',$r->get_package(),$r->get_quality_evaluation(),array_merge($r->get_traceability(),array('operation'=>'human_approval','approved_by'=>get_current_user_id(),'approved_at'=>current_time('mysql',true))));if(!$this->repository->update($approved))return new WP_REST_Response(array('success'=>false,'message'=>'Approval could not be persisted.'),500);return rest_ensure_response(array('success'=>true,'data'=>$approved->to_array(),'message'=>'Article Package approved. Publishing remains a separate operation.'));}
	public function rest_generate($request){$brief=$request->get_json_params();$brief=is_array($brief)?$brief:array();$brief['content_brief_id']=absint($request->get_param('content_brief_id'));$brief['post_id']=absint($request->get_param('post_id')?:($brief['post_id']??0));$r=$this->generator->generate($brief,get_current_user_id());if(is_wp_error($r))return new WP_REST_Response(array('success'=>false,'message'=>$r->get_error_message()),502);return rest_ensure_response(array('success'=>true,'data'=>$r));}
	public function render(){
	$error='';$result=null;$brief=array('content_brief_id'=>absint($_REQUEST['content_brief_id']??0),'post_id'=>absint($_REQUEST['post_id']??0),'topic'=>sanitize_text_field($_REQUEST['topic']??''),'primary_keyword'=>sanitize_text_field($_REQUEST['primary_keyword']??''),'search_intent'=>sanitize_text_field($_REQUEST['search_intent']??''),'content_type'=>sanitize_text_field($_REQUEST['content_type']??''),'target_audience'=>sanitize_text_field($_REQUEST['target_audience']??''),'main_entity'=>sanitize_text_field($_REQUEST['main_entity']??''),'related_entities'=>sanitize_text_field($_REQUEST['related_entities']??''),'authority_context'=>sanitize_text_field($_REQUEST['authority_context']??''),'internal_link_targets'=>sanitize_textarea_field($_REQUEST['internal_link_targets']??''),'author_id'=>absint($_REQUEST['author_id']??0));
	if('POST'===($_SERVER['REQUEST_METHOD']??'')){if(isset($_POST['amanah_generate_article'])){check_admin_referer('amanah_generate_article');$result=$this->generator->generate($brief,get_current_user_id());}elseif(isset($_POST['amanah_refine_article'])){check_admin_referer('amanah_refine_article');$latest=$this->repository->latest($brief['content_brief_id']);$instruction=sanitize_textarea_field($_POST['refinement_instruction']??'');$result=$latest?$this->generator->refine($brief,$latest->get_package(),get_current_user_id(),$instruction):new WP_Error('refinement_source_missing','No existing Article Package is available for refinement.');}elseif(isset($_POST['amanah_approve_article'])){check_admin_referer('amanah_approve_article');$latest=$this->repository->latest($brief['content_brief_id']);if(!$latest)$result=new WP_Error('article_package_missing','Article Package not found.');elseif('READY_FOR_HUMAN_REVIEW'!==$latest->get_status())$result=new WP_Error('article_package_not_ready','Article Package is not ready for human approval.');else{$approved=new AMANAH_SEO_AI_Article_Package($latest->get_package_id(),$latest->get_content_brief_id(),$latest->get_version(),$latest->get_parent_version(),'HUMAN_APPROVED',$latest->get_package(),$latest->get_quality_evaluation(),array_merge($latest->get_traceability(),array('operation'=>'human_approval','approved_by'=>get_current_user_id(),'approved_at'=>current_time('mysql',true))));$result=$this->repository->update($approved)?$approved->to_array():new WP_Error('approval_persistence_failed','Approval could not be persisted.');}}if(is_wp_error($result)){$error=$result->get_error_message();$result=null;}}
	if(!$result&&$brief['content_brief_id']){$latest=$this->repository->latest($brief['content_brief_id']);if($latest)$result=$latest->to_array();}
	require AMANAH_SEO_AI_PATH.'modules/content/views/content-generation.php';
}
}